\label{prop:unramified-local-pullback}
  Let \(v\) be a finite place at which \(\pi_{f,v}\) and the local Siegel section are unramified,
  and let \(\varphi_v\in\pi_{f,v}^{K_{r,v}}\).
  Then,
  for every \(g_1\in G_n(F_v)\),
  \begin{align*}
     & \int_{G_r(F_v)} \varepsilon_{n+r,v}^{\calO_{F_v}} \left( \xi_r\iota_{n,r}(g_1,g_2), \frac{\mu}{2};\chi_v \right) \overline{\varphi_v^\dagger(g_2)} \,dg_2 \\ & \quad= L_v\!\left(\frac{\mu-2r+1}{2},\pi_{f,v}, \St\right) \prod_{a=0}^{2r-1}L_{F,v}(\mu-a,\chi_{0,v}\chi_{E/F,v}^{a})^{-1} \Psi_{n,r,v}^{\calO_{F_v}} \left( \varphi_v; g_1, \frac{\mu}{2};\chi_v \right).
  \end{align*}

\label{prop:arche-local-pullback}
  Put \(\pi_{f,\infty}=\bigotimes_{v\in\bfa}\pi_{f,v}\).
  For \(\varphi_\infty\in\pi_{f,\infty}\) in the holomorphic \(K_{r,\infty}\)-type corresponding to \(\rho_r\),
  define \(\varphi_\infty^\dagger\) componentwise by the same involution.
  Then,
  for every \(g_1\in G_n(\bbA_{F,\infty})\),
  \[
    \int_{G_r(\bbA_{F,\infty})} \left\langle \bbD_{\bfk,\bfl} \varepsilon_{n+r,\infty}^{\hol} \left( \xi_r\iota_{n,r}(g_1,g_2), \frac{\mu}{2};\chi_{\bfa} \right), \varphi_\infty^\dagger(g_2) \right\rangle \,dg_2 = c_\infty \Psi_{n,r,\infty}^{\hol} \left( \varphi_\infty; g_1, \frac{\mu}{2};\chi_{\bfa} \right),
  \]
  where
  \begin{align*}
    c_\infty ={} & 2^{-d_F(2r^2+(r-2)\mu)+d_{\bfk,\bfl}} \pi^{d_Fr^2} \prod_{v\in\bfa} \prod_{i=1}^{r} \prod_{t=0}^{r-1} (k_{v,i}+l_{v,i}+\mu-i-t)^{-1} \\ & \times \prod_{v\in\bfa} \frac{ \prod_{i=1}^{\ell(\bfk_v)} (k_{v,i}+\ell(\bfk_v)-i)! }{ \prod_{1\le i<j\le\ell(\bfk_v)} (k_{v,i}-k_{v,j}+j-i) } \prod_{v\in\bfa} \frac{ \prod_{i=1}^{\ell(\bfl_v)} (l_{v,i}+\ell(\bfl_v)-i)! }{ \prod_{1\le i<j\le\ell(\bfl_v)} (l_{v,i}-l_{v,j}+j-i) }.
  \end{align*}

\label{def:primitive-lattice-poset}
  Let \(\calP_{\gamma,\frakN}^{(n)}(T)\) be the set of projective \(\calO_E\)-lattices \(M\subset E^n\) such that
  \begin{enumerate}
    \item \(L_{\gamma,\frakN}^{(n)}\subseteq M\subseteq(L_{\gamma,\frakN}^{(n)})_T^\sharp\);
    \item \(x^*Tx\in\frakd_F^{-1}\) for every \(x\in M\);
    \item \(M_v=L_{\gamma,\frakN,v}^{(n)}\) for every \(v\mid\frakN\).
  \end{enumerate}

\label{def:primitive-coefficient}
  Let \(F_0\) be an automorphic form on \(G_n\) of weight \(\rho\) and level \(K_n(\frakN)\).
  We define its primitive Fourier coefficient at \((\gamma,T)\) by
  \begin{align*}
    A_{F_0}^{\prim}(\gamma,T)
     & =
    \sum_{M\in\calP_\gamma(T)}
    \mu_{\calP_\gamma(T)}(L_{\gamma,\frakN}^{(n)},M)
    A_{F_0}(t_{n,0}(h_M)\gamma,T) \\
     & =
    \sum_{M\in\calP_\gamma(T)}
    \mu_{\calP_\gamma(T)}(L_{\gamma,\frakN}^{(n)},M)
    \rho_{T_M}[a_M,Z_M]
    A_{F_0}(\gamma[M],T_M).
  \end{align*}

\label{lem:primitive-reconstruction}
  For \(M\in\calP_\gamma(T)\), the map
  \[
    \begin{aligned}
      \{N\in\calP_\gamma(T):M\subseteq N\}
        & \xrightarrow{\sim}
      \calP_{\gamma[M]}(T_M), \\
      N & \longmapsto a_MN
    \end{aligned}
  \]
  is an isomorphism of posets.
  Moreover,
  \begin{equation}\label{eq:primitive-reconstruction}
    A_{F_0}(\gamma,T)
    =
    \sum_{M\in\calP_\gamma(T)}
    \rho_{T_M}[a_M,Z_M]
    A_{F_0}^{\prim}(\gamma[M],T_M).
  \end{equation}

\label{thm:main-petersson-formula}
  Assume \(\mu\ge n+r\).
  If \(\mu=n+r+1\) and \(F=\bbQ\), assume \(\chi_0\ne\chi_{E/F}^{n+r+1}\).
  If \(\mu=n+r\) and \(n=r+1\), assume that \(L^{(\frakN)}(1,f,\St)\) is holomorphic and nonzero.
  Then, for every \(\gamma\in\calC^{(n)}(\frakN)\) and
  \(T\in\Lambda_\gamma(\frakN)_{>0}\),
  \begin{equation}\label{eq:general-r-arithmetic-primitive}
    c_fA_{\Kl}^{\prim}(\gamma,T)
    =
    A_{\Si}^{\prim}(\gamma,T)
    \frac{(\Phi_{\gamma,T},f^\dagger)_{G_r}}
    {(f^\dagger,f^\dagger)_{G_r}}.
  \end{equation}
